# frozen_string_literal: true

# A counter that can be safely shared between threads.
#
#   counter = Counter.new
#   counter.increment      # => 1
#   counter.increment(5)   # => 6
#   counter.decrement      # => 5
#   counter.value          # => 5
class Counter
  def initialize(initial = 0)
    @value = initial
    @mutex = Mutex.new
  end

  # Adds +by+ to the counter and returns the new value.
  def increment(by = 1)
    @mutex.synchronize { @value += by }
  end

  # Subtracts +by+ from the counter and returns the new value.
  def decrement(by = 1)
    @mutex.synchronize { @value -= by }
  end

  def value
    @mutex.synchronize { @value }
  end

  # Sets the counter back to +to+ and returns the previous value.
  def reset(to = 0)
    @mutex.synchronize do
      previous = @value
      @value = to
      previous
    end
  end

  # Atomically replaces the value with the result of the block, which
  # receives the current value. Returns the new value. The block runs
  # while the lock is held, so it must not call back into this counter.
  def update
    @mutex.synchronize { @value = yield(@value) }
  end
end
